        Cow bessy = new Cow("Bessy", 1.5, 800, "White and Black");
        Cat whiskers = new Cat("Whiskers", 0.3, 4, "Ginger");
        Dog buddy = new Dog("Buddy", 0.6, 25, "Golden");

